import json, math, itertools, sys
sys.set_int_max_str_digits(0)
def i(x): return f'<i>{x}</i>'
def q(n,text,p): return f'<div class="q"><span class="n">({n})</span> {text} <span class="p">[{p}점]</span></div>'
def passage(*ps): return '<div class="passage">'+''.join(f'<p>{p}</p>' for p in ps)+'</div>'
def ol(*items): return '<ol>'+''.join(f'<li>{x}</li>' for x in items)+'</ol>'
def h3(t): return f'<h3>{t}</h3>'
def ans(t): return f'<p class="ans-line">{t}</p>'
def read(t): return f'<div class="read"><b>문해력 포인트.</b> {t}</div>'
def check(t,label='스스로 점검'): return f'<div class="read"><b>{label}.</b> {t}</div>'
def pit(t): return f'<div class="pitfall"><b>자주 하는 실수.</b> {t}</div>'
P=[]
def add(id,title,topic,tag,level,body,sol,rubric):
    assert sum(r[1] for r in rubric)==20,(id,sum(r[1] for r in rubric))
    P.append(dict(id=id,title=title,topic=topic,tag=tag,level=level,pts=20,min=20,ah=100,body=body,sol=sol,rubric=[{'t':t,'p':p} for t,p in rubric],src='추가 문제 세트'))

# ---------- N1 숫자 압축기 ----------
f=lambda n:sum(map(int,str(n)))
def g(n):
    while n>=10:n=f(n)
    return n
assert (f(2027),g(2027),g(98765))==(11,2,8) and sum(1 for n in range(1,101) if g(n)==7)==11 and g(pow(2026,2026))==1
add('b-n1','숫자 압축기','number','정수론 · 나머지','중',
 passage('발명교육센터의 “숫자 압축기”는 자연수 '+i('n')+'을 넣으면 각 자리 숫자를 모두 더한 값 '+i('f')+'('+i('n')+')을 내보낸다. 예를 들어 '+i('f')+'(2027) = 2 + 0 + 2 + 7 = 11이다.','압축기에 나온 수를 다시 넣는 일을 <b>한 자리 수가 나올 때까지</b> 반복해서 얻는 마지막 수를 '+i('g')+'('+i('n')+')이라 하자. 예를 들어 2027 → 11 → 2이므로 '+i('g')+'(2027) = 2이다.')
 +q(1,'<i>g</i>(98765)를 구하고, <i>f</i>(<i>n</i>) = <i>n</i>이 되는 두 자리 이하의 자연수 <i>n</i>이 어떤 수인지 쓰시오.',3)
 +q(2,'자연수 <i>n</i>에 대해 <i>n</i> − <i>f</i>(<i>n</i>)이 <b>9의 배수</b>임을 증명하시오. (세 자리 수 <i>n</i> = 100<i>a</i> + 10<i>b</i> + <i>c</i>로 시작해도 좋으나, 자릿수가 많아져도 같은 이유가 성립함을 설명하시오.)',5)
 +q(3,'(2)를 이용해 <i>g</i>(<i>n</i>)이 <i>n</i>을 9로 나눈 나머지와 어떤 관계인지 알아내고(나머지가 0일 때도 답하시오), 그 이유를 쓰시오.',6)
 +q(4,'① 1부터 100까지의 자연수 중 <i>g</i>(<i>n</i>) = 7인 수는 모두 몇 개인지 구하시오. ② <i>g</i>(2026<sup>2026</sup>)을 구하시오.',6),
 read('“한 자리 수가 나올 때까지 반복”이라는 문장은 <b>압축할 때마다 9의 배수만큼만 줄어든다</b>는 관찰로 이어집니다. (2)에서 증명한 사실이 (3)·(4)의 도구입니다.')
 +h3('(1) 계산')+ol('98765 → 9+8+7+6+5 = 35 → 3+5 = 8. 따라서 <i>g</i>(98765) = 8.','<i>f</i>(<i>n</i>) = <i>n</i>이려면 한 자리 수여야 합니다(두 자리 이상이면 자리의 합이 원래 수보다 작기 때문). 따라서 1~9의 한 자리 수가 전부입니다. (0은 자연수가 아닙니다.)')+ans('g(98765) = 8, 한 자리 수 1~9')
 +h3('(2) n − f(n)은 9의 배수')+ol('세 자리 수 <i>n</i> = 100<i>a</i> + 10<i>b</i> + <i>c</i>이면 <i>f</i>(<i>n</i>) = <i>a</i> + <i>b</i> + <i>c</i>입니다.','<i>n</i> − <i>f</i>(<i>n</i>) = 99<i>a</i> + 9<i>b</i> = 9(11<i>a</i> + <i>b</i>)이므로 9의 배수입니다.','일반적으로 10<sup>k</sup> − 1 = 99…9(9가 <i>k</i>개)는 9의 배수이므로, 어느 자리의 숫자 <i>d</i>도 <i>d</i>·10<sup>k</sup> − <i>d</i> = <i>d</i>(10<sup>k</sup> − 1)이 9의 배수입니다. 모든 자리에 대해 더하면 <i>n</i> − <i>f</i>(<i>n</i>)도 9의 배수입니다.')+ans('자리마다 d(10^k − 1)이 9의 배수이므로 n − f(n)은 9의 배수')
 +h3('(3) g(n)과 9로 나눈 나머지')+ol('(2)에 의해 <i>f</i>(<i>n</i>)과 <i>n</i>은 9로 나눈 나머지가 같습니다. <i>f</i>를 몇 번 적용해도 나머지는 변하지 않습니다.','따라서 <i>g</i>(<i>n</i>)은 <i>n</i>을 9로 나눈 나머지와 같습니다. 단 <i>g</i>(<i>n</i>)은 1~9인 한 자리 수이므로(자연수의 자리 합은 항상 1 이상), 나머지가 0이면 <i>g</i>(<i>n</i>) = 9입니다.','예: 99 → 18 → 9, 99 = 9 × 11이므로 나머지 0일 때 9.')+ans('g(n)은 n을 9로 나눈 나머지(나머지가 0이면 9)')
 +pit('나머지가 0이면 g(n) = 0이라고 쓰는 것. 압축을 반복해도 자연수의 자리 합은 1 이상이므로 0이 될 수 없습니다.')
 +h3('(4) 개수와 큰 수')+ol('① <i>g</i>(<i>n</i>) = 7이면 <i>n</i>을 9로 나눈 나머지가 7입니다. <i>n</i> = 7, 16, 25, …, 97 (7 + 9<i>k</i>, <i>k</i> = 0~10)이고 다음은 106 > 100입니다. 따라서 <b>11개</b>.','② 2026을 9로 나누면 2026 = 9 × 225 + 1이므로 나머지 1입니다.','나머지가 1인 수를 여러 번 곱해도 나머지는 1입니다(1 × 1 = 1). 따라서 2026<sup>2026</sup>을 9로 나눈 나머지도 1이고, <i>g</i>(2026<sup>2026</sup>) = 1.')+ans('① 11개 ② 1')
 +check('2026 대신 2027, 2028을 넣으면 g의 값은 어떻게 변할까요? (힌트: 2027 ≡ 2, 2028 ≡ 3이고 거듭제곱의 나머지는 규칙적으로 반복합니다.)'),
 [('(1) g(98765) = 8과 한 자리 수 1~9',3),('(2) 99a + 9b = 9(11a + b) 식으로 보임',2),('(2) 자릿수가 많아도 d(10^k − 1)이 9의 배수라는 이유 설명',3),('(3) n과 f(n)의 9로 나눈 나머지가 같다고 결론',2),('(3) 나머지가 0이면 9임을 근거(자리 합 ≥ 1)와 함께 서술',4),('(4) ① 7, 16, …, 97 → 11개',3),('(4) ② 2026 ≡ 1이라서 거듭제곱도 1, g = 1',3)])

# ---------- N2 동전 ----------
def reach(a,b,L=200):
    return {a*x+b*y for x in range(L//a+1) for y in range(L//b+1)}
r=reach(3,5);assert [n for n in range(40) if n not in r]==[1,2,4,7]
r=reach(4,7);un=[n for n in range(100) if n not in r];assert un[-1]==17 and len(un)==9
add('b-n2','3원과 5원만 있는 가게','number','정수론 · 존재 증명','중상',
 passage('어느 가게에는 <b>3원짜리와 5원짜리 동전만</b> 있다. 각 동전은 몇 개든 쓸 수 있고, 거스름돈 없이 정확히 그 금액만큼만 낼 수 있어야 “만들 수 있는 금액”이라고 한다. 예를 들어 11 = 3 + 3 + 5이므로 11원은 만들 수 있다.')
 +q(1,'1원부터 10원까지 중 <b>만들 수 없는 금액</b>을 모두 찾으시오.',4)
 +q(2,'8원 이상의 금액은 <b>모두</b> 만들 수 있음을 증명하시오.',6)
 +q(3,'동전이 4원짜리와 7원짜리일 때, 만들 수 없는 금액 중 <b>가장 큰 값</b>과 만들 수 없는 금액의 <b>개수</b>를 구하시오.',5)
 +q(4,'서로소인 두 자연수 <i>a</i>, <i>b</i>에 대해, 금액 <i>ab</i> − <i>a</i> − <i>b</i>는 <i>a</i>원, <i>b</i>원 동전으로 만들 수 <b>없음</b>을 증명하시오. ((3)의 결과가 이 식과 일치하는지도 확인하시오.)',5),
 read('“만들 수 있다 = 3<i>x</i> + 5<i>y</i> (<i>x</i>, <i>y</i>는 0 이상의 정수)로 쓸 수 있다”로 번역하는 것이 첫걸음입니다. (2)는 <b>연속된 3개</b>가 만들어지면 거기서 3씩 더해 모두 만들 수 있다는 아이디어입니다.')
 +h3('(1) 직접 확인')+ol('1, 2, 4, 7을 제외한 나머지를 확인합니다. 3 = 3, 5 = 5, 6 = 3+3, 8 = 3+5, 9 = 3+3+3, 10 = 5+5.','1, 2는 3, 5보다 작고, 4는 3 + 1이 필요, 7은 3 + 4, 5 + 2가 모두 안 되고 3·5의 조합으로 7을 만들 수 없습니다.')+ans('1, 2, 4, 7원')
 +h3('(2) 8 이상은 모두 가능')+ol('8 = 3 + 5, 9 = 3 × 3, 10 = 5 × 2. 연속된 세 수 8, 9, 10이 만들어집니다.','8 이상의 임의의 수 <i>N</i>은 8, 9, 10 중 하나에 3을 몇 번 더한 값입니다. (<i>N</i>을 3으로 나눈 나머지에 따라 8, 9, 10 중 맞는 것을 고르면 됩니다.)','8, 9, 10에 3을 더한 수도 모두 3과 5의 합이므로, 8 이상은 모두 만들 수 있습니다.')+ans('연속 3개(8, 9, 10)에서 3씩 더하면 모든 8 이상 가능')
 +pit('8, 9, 10, 11, 12까지 몇 개만 확인하고 “모두 가능하다”고 쓰는 것. 연속 3개가 되면 무한히 이어진다는 이유를 반드시 써야 합니다.')
 +h3('(3) 4원, 7원')+ol('4<i>x</i> + 7<i>y</i>로 나타내어 봅니다. 만들 수 있는 수: 0, 4, 7, 8, 11, 12, 14, 15, 16, 18, 19, 20, 21, …','연속 4개 18, 19, 20, 21이 모두 가능하므로(18 = 4 + 7 + 7, 19 = 4 × 3 + 7, 20 = 4 × 5, 21 = 7 × 3) 4씩 더하면 18 이상은 모두 가능합니다.','17은 4<i>x</i> + 7<i>y</i> = 17에서 <i>y</i> = 0, 1, 2일 때 17, 10, 3이 4의 배수가 아니므로 불가능.','만들 수 없는 수: 1, 2, 3, 5, 6, 9, 10, 13, 17 → <b>9개</b>.')+ans('가장 큰 값 17, 개수 9')
 +h3('(4) ab − a − b 불가능')+ol('<i>ab</i> − <i>a</i> − <i>b</i> = <i>ax</i> + <i>by</i> (<i>x</i>, <i>y</i> ≥ 0)라고 가정합니다.','양변에 <i>a</i> + <i>b</i>를 더하면 <i>a</i>(<i>x</i> + 1) + <i>b</i>(<i>y</i> + 1) = <i>ab</i>.','<i>a</i>(<i>x</i>+1)은 <i>a</i>의 배수이고 <i>ab</i>도 <i>a</i>의 배수이므로 <i>b</i>(<i>y</i>+1)이 <i>a</i>의 배수입니다. <i>a</i>, <i>b</i>가 서로소이므로 <i>y</i> + 1이 <i>a</i>의 배수, 즉 <i>y</i> + 1 ≥ <i>a</i>입니다.','같은 방식으로 <i>x</i> + 1 ≥ <i>b</i>입니다.','그러면 <i>a</i>(<i>x</i>+1) + <i>b</i>(<i>y</i>+1) ≥ <i>ab</i> + <i>ab</i> = 2<i>ab</i> > <i>ab</i>로 모순입니다. 따라서 불가능합니다.','(3)의 확인: 4 × 7 − 4 − 7 = 17 (일치). (1)의 3, 5도 15 − 3 − 5 = 7 (일치).')+ans('귀류법: y+1 ≥ a, x+1 ≥ b이면 합이 2ab > ab로 모순')
 +check('두 동전이 서로소가 아니면(예: 4원, 6원) 만들 수 없는 금액이 무한히 많습니다. 왜일까요?'),
 [('(1) 만들 수 없는 1, 2, 4, 7 모두 찾음(7이 만들어지지 않는 이유 포함)',4),('(2) 8, 9, 10이 만들어짐을 보임',2),('(2) 3씩 더해 모든 8 이상이 만들어진다는 논증',4),('(3) 17이 불가능하고 18 이상이 가능함을 보임',3),('(3) 개수 9를 바르게 셈',2),('(4) 귀류법 세팅과 a(x+1)+b(y+1)=ab 변형',2),('(4) 서로소를 써서 y+1 ≥ a, x+1 ≥ b 유도',2),('(4) 모순 결론과 (3)과의 일치 확인',1)])

# ---------- C1 발표 순서 ----------
perm=list(itertools.permutations('ABCDEF'))
assert len(perm)==720 and sum(1 for p in perm if abs(p.index('A')-p.index('B'))==1)==240 and sum(1 for p in perm if abs(p.index('A')-p.index('B'))==2)==192 and sum(1 for p in perm if p.index('A')<p.index('B')<p.index('C'))==120
add('b-c1','발명 대회 발표 순서','combi','조합 · 경우의 수','중',
 passage('발명 대회에서 여섯 팀 A, B, C, D, E, F가 한 줄로 순서를 정해 한 팀씩 발표한다. 모든 팀의 발표 순서가 다르며, 순서가 다르면 다른 경우로 센다.')
 +q(1,'발표 순서를 정하는 방법은 모두 몇 가지인가?',3)
 +q(2,'A팀과 B팀이 <b>바로 이웃해서</b> 발표하는 경우는 몇 가지인가? 풀이 과정을 쓰시오.',5)
 +q(3,'A팀과 B팀 사이에 <b>정확히 한 팀</b>이 발표하는 경우는 몇 가지인가? (A가 앞이든 B가 앞이든 모두 센다.)',6)
 +q(4,'A팀이 B팀보다 먼저, B팀이 C팀보다 먼저 발표하는 경우는 몇 가지인가? 그렇게 되는 이유를 “경우의 수를 직접 세지 않고” 설명하시오.',6),
 read('(2)는 “이웃”이라는 말 때문에 <b>A, B를 하나로 묶는 아이디어</b>로 이어집니다. (3)은 “사이에 정확히 한 팀”이므로 A, 중간 팀, B가 이웃한 <b>세 칸 덩어리</b>를 이룹니다. (4)는 팀 이름이 아니라 <b>순서의 모양</b>을 센다고 읽으면 됩니다.')
 +h3('(1) 전체')+ol('첫 번째 칸 6가지, 다음 5가지, … 곱의 법칙으로 6 × 5 × 4 × 3 × 2 × 1 = 720.')+ans('720가지')
 +h3('(2) A, B 이웃')+ol('A, B를 하나의 묶음으로 보면 묶음과 나머지 네 팀, 모두 5개를 줄 세우는 경우가 5! = 120가지입니다.','묶음 안에서 A가 앞이거나 B가 앞인 2가지가 있습니다.','120 × 2 = 240.')+ans('240가지')
 +pit('묶음 안의 순서(×2)를 빼먹는 것.')
 +h3('(3) 사이에 한 팀')+ol('A, B 사이에 올 팀을 먼저 고릅니다. 남은 네 팀 중 하나이므로 4가지.','“A, 가운데 팀, B”(또는 B, 가운데 팀, A)를 세 칸짜리 덩어리 하나로 봅니다. 덩어리 안에서 A, B의 순서가 2가지.','덩어리와 나머지 세 팀, 모두 4개를 줄 세우는 경우 4! = 24가지.','곱하면 4 × 2 × 24 = 192.','<b>다른 풀이:</b> A, B의 위치가 (1, 3), (2, 4), (3, 5), (4, 6)의 4가지 쌍이고 A, B 순서 2가지, 가운데 칸에 오는 팀 4가지, 남은 3팀이 남은 3칸에 3! = 6가지. 4 × 2 × 4 × 6 = 192.')+ans('192가지')
 +h3('(4) A → B → C 순서')+ol('A, B, C가 차지하는 세 칸을 정하면, 그 세 칸에 A, B, C가 들어가는 순서는 3! = 6가지입니다. 그중 A, B, C 순서인 경우는 정확히 1가지.','따라서 전체 720가지에서 이 세 팀의 순서가 6가지로 똑같이 나뉘므로 720 ÷ 6 = 120.')+ans('120가지')
 +check('A가 B보다 먼저, 그리고 C가 D보다 먼저 발표하는 경우는 몇 가지일까요? (답: 180)'),
 [('(1) 720가지',3),('(2) A, B를 묶어 5!로 세는 아이디어',3),('(2) 묶음 안 순서 ×2를 반영해 240',2),('(3) 가운데 팀 4가지와 A, B 순서 2가지를 구함',3),('(3) 덩어리와 나머지 팀 4!로 192',3),('(4) 세 팀의 순서가 모두 6가지로 똑같이 나뉜다는 설명',3),('(4) 720 ÷ 6 = 120',3)])

# ---------- C2 비인접 선택 ----------
assert math.comb(6,3)==20 and math.comb(6,2)+math.comb(7,3)==50 and math.comb(7,3)+math.comb(8,4)==105
add('b-c2','이웃하지 않는 자리','combi','조합 · 이웃하지 않는 선택','중상',
 passage('전시장의 조명 스위치가 한 줄로 늘어서 있다. 안전을 위해 <b>이웃한 두 스위치를 동시에 켜면 안 된다</b>. 켤 스위치를 정하는 방법의 수를 센다.')
 +q(1,'스위치가 일렬로 8개 있을 때, 3개를 켜는 방법은 몇 가지인가? (이웃한 것을 동시에 켜지 않는다.)',4)
 +q(2,'스위치가 일렬로 <i>n</i>개 있고 <i>k</i>개를 켤 때의 방법의 수가 <i>C</i>(<i>n</i> − <i>k</i> + 1, <i>k</i>)임을 설명하시오. (켜진 것의 번호를 작은 것부터 <i>a</i><sub>1</sub> &lt; <i>a</i><sub>2</sub> &lt; ⋯로 놓고 일대일 대응을 이용하시오.)',6)
 +q(3,'스위치가 <b>원형</b>으로 10개 놓여 있다(10번과 1번도 이웃). 3개를 켜는 방법은 몇 가지인가?',6)
 +q(4,'원형으로 12개 놓여 있을 때 4개를 켜는 방법은 몇 가지인가?',4),
 read('“이웃한 두 개를 동시에 켜지 않는다”는 것은 켜진 스위치 사이에 <b>꺼진 스위치가 적어도 하나</b> 있다는 뜻입니다. (2)의 일대일 대응은 켜진 스위치 사이의 꺼진 스위치를 하나씩 “지워서” 조건을 없애는 아이디어입니다. 원형은 1번을 켰는지 안 켰는지로 <b>나누어 직선 문제로 바꿉니다</b>.')
 +h3('(1) 직선 8개, 3개 켜기')+ol('켜지는 번호를 <i>a</i> &lt; <i>b</i> &lt; <i>c</i>라 하면 <i>b</i> ≥ <i>a</i> + 2, <i>c</i> ≥ <i>b</i> + 2입니다.','<i>a</i>, <i>b</i> − 1, <i>c</i> − 2로 바꾸면 1 ≤ <i>a</i> &lt; <i>b</i> − 1 &lt; <i>c</i> − 2 ≤ 6이 되어, 1~6에서 서로 다른 3개를 고르는 방법과 일대일 대응합니다.','<i>C</i>(6, 3) = 20.')+ans('20가지')
 +h3('(2) 일반식')+ol('켜진 번호 <i>a</i><sub>1</sub> &lt; <i>a</i><sub>2</sub> &lt; ⋯ &lt; <i>a</i><sub><i>k</i></sub>에서 <i>a</i><sub><i>j</i></sub>를 <i>a</i><sub><i>j</i></sub> − (<i>j</i> − 1)로 바꿉니다(<i>j</i>번째 것에서 앞의 꺼진 칸 <i>j</i> − 1개를 지운다고 생각).','이웃하지 않으므로 <i>a</i><sub><i>j</i>+1</sub> − <i>a</i><sub><i>j</i></sub> ≥ 2이고, 바꾼 값은 <i>b</i><sub><i>j</i>+1</sub> − <i>b</i><sub><i>j</i></sub> ≥ 1, 즉 순증가입니다. 마지막 값은 <i>a</i><sub><i>k</i></sub> − (<i>k</i> − 1) ≤ <i>n</i> − <i>k</i> + 1.','따라서 <i>b</i><sub>1</sub> &lt; ⋯ &lt; <i>b</i><sub><i>k</i></sub> 는 1~(<i>n</i> − <i>k</i> + 1)에서 <i>k</i>개를 고른 것이고, 거꾸로 이런 선택에서 되돌릴 수 있으므로 일대일 대응입니다. 개수는 <i>C</i>(<i>n</i> − <i>k</i> + 1, <i>k</i>). (1)에서 <i>n</i> = 8, <i>k</i> = 3이면 <i>C</i>(6, 3).')+ans('C(n − k + 1, k) (켜진 것 사이 꺼진 칸 1개씩 지우는 일대일 대응)')
 +h3('(3) 원형 10개, 3개')+ol('1번이 <b>켜진</b> 경우: 2번과 10번이 꺼져야 합니다. 3~9번(7개, 일렬)에서 2개를 켭니다. (2)에서 <i>C</i>(7 − 2 + 1, 2) = <i>C</i>(6, 2) = 15.','1번이 <b>꺼진</b> 경우: 2~10번(9개, 일렬)에서 3개를 켭니다. (원형의 이웃 조건 중 10번과 1번은 1번이 꺼져 있어 신경 쓰지 않아도 됩니다.) <i>C</i>(9 − 3 + 1, 3) = <i>C</i>(7, 3) = 35.','합: 15 + 35 = 50.')+ans('50가지')
 +pit('원형이라고 해서 10번과 1번의 이웃 관계를 빼먹는 것. 1번이 켜졌을 때 10번도 꺼야 합니다.')
 +h3('(4) 원형 12개, 4개')+ol('1번 켬: 2번, 12번 끔 → 3~11번(9개 일렬)에서 3개: <i>C</i>(9 − 3 + 1, 3) = <i>C</i>(7, 3) = 35.','1번 끔: 2~12번(11개 일렬)에서 4개: <i>C</i>(11 − 4 + 1, 4) = <i>C</i>(8, 4) = 70.','합: 35 + 70 = 105.')+ans('105가지')
 +check('공식 12/(12 − 4) × C(12 − 4, 4) = 105와 같음을 확인해 보세요. 원형 10개 3개도 10/7 × C(7, 3) = 50입니다.'),
 [('(1) 번호 변환(예: a, b−1, c−2)으로 C(6,3)에 대응시킴',2),('(1) 20가지',2),('(2) 번호를 j−1만큼 줄이는 대응 설정',2),('(2) 순증가임과 범위 n−k+1을 보임',2),('(2) 일대일 대응(역변환 가능)과 결론 C(n−k+1,k)',2),('(3) 1번을 켠 경우 C(6,2) = 15',2),('(3) 1번을 끈 경우 C(7,3) = 35, 합 50',4),('(4) 35 + 70 = 105',4)])
json.dump(P,open('bank2a.json','w',encoding='utf8'),ensure_ascii=False)
print(len(P),'ok')
